  environment {
    NPM_AUDIT = 'false'
    NPM_BUILD_COMMAND = 'npm run build'
    NPM_CACHE_ENABLED = 'true'
    NPM_CLEAN_CACHE = 'false'
    NPM_INSTALL_COMMAND = 'npm install'
    NPM_LEGACY_PEER_DEPS = 'false'
    NPM_OUTPUT_DIR = 'dist'
    NPM_TIMEOUT_MINUTES = '30'
    PIPELINE_CODE = 'vue-build'
    PIPELINE_ENV = 'jb-dev'
    PIPELINE_ENV_NAME = '北京-测试环境'
    PIPELINE_NAME = '前端流水线-A'
    PROJECT_CODE = 'proj-20260428142221-542000'
    SYSTEM_CODE = 'test'
    SYSTEM_NAME = '测试'
    TARGET_DIR = '.'
  }
  stages {
    stage('自定义确认信息') {
      steps {
        input message: params.CHECK_PROMPT_MESSAGE, ok: params.CHECK_OK_BUTTON_TEXT
      }
    }
    stage('Git代码克隆') {
      steps {
        script {
            /***********************
            * 按顺序定义执行变量
            ***********************/

            String gitRepoUrl = params.GIT_REPO_URL.trim()

            String gitCredentialsId = params.GIT_CREDENTIALS_ID.trim()

            String gitBranchName = params.GIT_BRANCH_NAME.trim()

            String gitTargetDir = params.GIT_TARGET_DIR.trim()

            Boolean gitCleanBeforeCheckout = params.GIT_CLEAN_BEFORE_CHECKOUT

            Boolean gitChangelog = params.GIT_CHANGELOG

            Integer gitShallowCloneDepth = params.GIT_SHALLOW_CLONE_DEPTH.trim().toInteger()

            Boolean gitEnableSubmodules = params.GIT_ENABLE_SUBMODULES

            Integer gitTimeoutMinutes = params.GIT_TIMEOUT_MINUTES.trim().toInteger()

            /***********************
            * 按顺序调用公共脚本
            ***********************/

            def gitCheckoutResult = gitCloneRepo(
            repoUrl: gitRepoUrl,
            credentialsId: gitCredentialsId,
            branchName: gitBranchName,
            targetDir: gitTargetDir,
            cleanBeforeCheckout: gitCleanBeforeCheckout,
            changelog: gitChangelog,
            shallowCloneDepth: gitShallowCloneDepth,
            enableSubmodules: gitEnableSubmodules,
            timeoutMinutes: gitTimeoutMinutes
            )

            echo "Git 克隆结果：${gitCheckoutResult}"
          }
      }
    }
    stage('并行组-1') {
      parallel {
        stage('Sonar扫描前端项目') {
          steps {
            script {
                def result = sonarScanVue(
                targetDir: params.SONAR_TARGET_DIR,
                sourcesDir: params.SONAR_SOURCES_DIR,
                sonarHostUrl: params.SONAR_HOST_URL,
                credentialsId: params.SONAR_CREDENTIALS_ID,
                projectKey: params.SONAR_PROJECT_KEY,
                projectVersion: env.BUILD_NUMBER ?: '',
                exclusions: params.SONAR_EXCLUSIONS,
                sonarUserHome: "${env.JENKINS_HOME}/sonar-cache",
                wsTimeout: (params.SONAR_WS_TIMEOUT ?: '30') as Integer,
                timeoutMinutes: (params.SONAR_TIMEOUT_MINUTES ?: '20') as Integer,
                tests: params.SONAR_TESTS,
                testInclusions: params.SONAR_TEST_INCLUSIONS,
                coverageExclusions: params.SONAR_COVERAGE_EXCLUSIONS,
                lcovReportPaths: params.SONAR_LCOV_REPORT_PATHS,
                tsconfigPaths: params.SONAR_TSCONFIG_PATHS,
                extraProperties: params.SONAR_EXTRA_PROPERTIES
                )

                echo "Vue Sonar 扫描结果：${result}"
              }
          }
        }
        stage('npm编译') {
          steps {
            script {
                // 只取 job name，例如：test-vue-build-jb-dev
                def jobName = env.JOB_BASE_NAME ?: (env.JOB_NAME ?: 'unknown-job').tokenize('/').last()

                def resolvedCacheDir = params.NPM_CACHE_DIR?.trim()
                if (!resolvedCacheDir) {
                  resolvedCacheDir = "${env.JENKINS_HOME}/npm-build-cache/${jobName}"
                }
                // 调用共享库，传入所有配置参数
                def result = npmBuildProject(
                // 基础参数
                targetDir              : env.TARGET_DIR,
                timeoutMinutes         : env.NPM_TIMEOUT_MINUTES,
                outputDir              : env.NPM_OUTPUT_DIR,

                // 命令
                installCommand         : env.NPM_INSTALL_COMMAND,
                buildCommand           : env.NPM_BUILD_COMMAND,

                // 缓存
                cacheEnabled           : env.NPM_CACHE_ENABLED,
                npmCacheDir            : resolvedCacheDir,
                cleanCacheBeforeInstall: env.NPM_CLEAN_CACHE,

                // 仓库认证（直接传参，无需 withCredentials）
                npmRegistry            : env.NPM_REGISTRY,
                npmRegistryUser        : env.NPM_REGISTRY_USER,
                npmRegistryPassword    : env.NPM_REGISTRY_PASSWORD,

                // npm 特性
                legacyPeerDeps         : env.NPM_LEGACY_PEER_DEPS,
                npmAudit               : env.NPM_AUDIT,
                )
              }
          }
        }
      }
    }
    stage('自定义命令') {
      steps {
        script {
            def result = commandSimpleRun(
            command: params.BASH_COMMANDS,
            printCommand: params.BASH_PRINT_COMMAND,
            timeoutMinutes: params.BASH_TIMEOUT_MINUTES as Integer
            )
          }
      }
    }
    stage('自定义命令-1') {
      steps {
        script {
            def result = commandSimpleRun(
            command: params.BASH_COMMANDS_2,
            printCommand: params.BASH_PRINT_COMMAND_2,
            timeoutMinutes: params.BASH_TIMEOUT_MINUTES_2 as Integer
            )
          }
      }
    }
    stage('docker构建镜像') {
      steps {
        script {
            // 只取 job name，例如：test-vue-build-jb-dev
            def jobName = env.JOB_BASE_NAME ?: (env.JOB_NAME ?: 'unknown-job').tokenize('/').last()

            def resolvedCacheDir = params.DOCKER_CACHE_DIR?.trim()
            if (!resolvedCacheDir) {
              resolvedCacheDir = "${env.JENKINS_HOME}/docker-build-cache/${jobName}"
            }

          // 调用共享库，传递核心参数
          def result = dockerBuildImage(
          registryUrl     : params.DOCKER_REGISTRY_URL,
          imageName       : params.DOCKER_IMAGE_NAME,
          credentialsId   : params.DOCKER_CREDENTIALS_ID,
          dockerfilePath  : params.DOCKER_DOCKERFILE_PATH,
          targetDir       : params.DOCKER_TARGET_DIR,
          imageTag        : params.DOCKER_IMAGE_TAG,
          tagStrategy     : params.DOCKER_TAG_STRATEGY,
          platforms       : params.DOCKER_PLATFORMS,
          cacheDir        : resolvedCacheDir,
          buildkitImage   : params.DOCKER_BUILDKIT_IMAGE
          )
        }
      }
    }
    stage('buildKit构建镜像') {
      steps {
        script {
            def result = buildkitBuildImage(
            buildkitAddr    : params.BUILDKIT_SERVER_ADDR,
            certificateCode : params.BUILDKIT_CERTIFICATE_CODE,
            registryUrl     : params.BUILDKIT_REGISTRY_URL,
            imageName       : params.BUILDKIT_IMAGE_NAME,
            credentialsId   : params.BUILDKIT_CREDENTIALS_ID,
            dockerfilePath  : params.BUILDKIT_DOCKERFILE_PATH,
            targetDir       : params.BUILDKIT_TARGET_DIR,
            imageTag        : params.BUILDKIT_IMAGE_TAG,
            tagStrategy     : params.BUILDKIT_TAG_STRATEGY,
            platforms       : params.BUILDKIT_PLATFORMS,
            cacheEnabled    : params.BUILDKIT_CACHE_ENABLED,
            cacheRef        : params.BUILDKIT_CACHE_REF
            )

            echo "镜像构建完成：${result.imageRef}"
          }
      }
    }
  }
  post {
    failure {
      script {
          def scriptContent = params.POST_FAILURE_SCRIPT
          // 直接执行整个多行脚本
          sh scriptContent
        }
    }
  }
}

