    booleanParam(name: 'BASH_PRINT_COMMAND', defaultValue: false, description: '不输出执行过程')
    string(name: 'BASH_TIMEOUT_MINUTES', defaultValue: '30', description: '命令执行生命周期', trim: true)
    text(name: 'BASH_COMMANDS_2', defaultValue: '''ls
pwd
ls -l''', description: '执行命令一行一个')
    booleanParam(name: 'BASH_PRINT_COMMAND_2', defaultValue: false, description: '不输出执行过程')
    string(name: 'BASH_TIMEOUT_MINUTES_2', defaultValue: '30', description: '命令执行生命周期', trim: true)
