    string(name: 'DOCKER_IMAGE_NAME', defaultValue: 'vue-test', description: '镜像名称', trim: true)
    string(name: 'DOCKER_CREDENTIALS_ID', defaultValue: 'kn-proj-20260428142221-542000-harbor-admin', description: '镜像仓库凭证', trim: true)
    string(name: 'DOCKER_TARGET_DIR', defaultValue: '.', description: 'Git clone 后的代码目录，同时也是执行 `docker buildx build` 的目录', trim: true)
    string(name: 'DOCKER_DOCKERFILE_PATH', defaultValue: 'manifestfiles/Dockerfile', description: 'Dockerfile 路径，相对于 `targetDir`', trim: true)
