    string(name: 'DOCKER_CACHE_DIR', defaultValue: '', description: '如果为空则自动配置 `${JENKINS_HOME}/docker-build-cache/${JOB_NAME}/`', trim: true)
    string(name: 'DOCKER_BUILDKIT_IMAGE', defaultValue: 'harbor.ikubeops.local/public/buildkit:buildx-stable-1', description: '不需要配置，', trim: true)
    string(name: 'BUILDKIT_REGISTRY_URL', defaultValue: 'https://harbor.ikubeops.local/public', description: '镜像仓库地址，可带项目路径', trim: true)
    string(name: 'BUILDKIT_IMAGE_NAME', defaultValue: 'test-vue', description: '	镜像名称，例如 test-vue', trim: true)
    string(name: 'BUILDKIT_CREDENTIALS_ID', defaultValue: 'kn-proj-20260428142221-542000-harbor-admin', description: 'Jenkins 镜像仓库账号密码凭证 ID', trim: true)
    string(name: 'BUILDKIT_DOCKERFILE_PATH', defaultValue: 'manifestfiles/Dockerfile', description: 'Dockerfile 路径，相对 BUILDKIT_TARGET_DIR', trim: true)
