    choice(name: 'BUILDKIT_TAG_STRATEGY', choices: ['date', 'commitId', 'branchCommId', 'tag', 'branchDate', 'imageTagDate'], description: '支持 date、commitId、branchCommId、tag、branchDate、imageTagDate')
    choice(name: 'BUILDKIT_CERTIFICATE_CODE', choices: ['dev'], description: '证书编码。空则不传证书；如 dev 则引用 src/buildKit/dev/ca.crt、client.crt、client.key')
    string(name: 'BUILDKIT_SERVER_ADDR', defaultValue: 'tcp://172.16.1.24:30082', description: 'BuildKit server 地址，例如 tcp://172.16.1.24:30082', trim: true)
