                  projectVersion: env.BUILD_NUMBER ?: '',
                  exclusions: params.SONAR_EXCLUSIONS,
                  sonarUserHome: resolvedSonarUserHome,
                  wsTimeout: (params.SONAR_WS_TIMEOUT ?: '30') as Integer,
                  timeoutMinutes: (params.SONAR_TIMEOUT_MINUTES ?: '20') as Integer,
                  tests: params.SONAR_TESTS,
                  testInclusions: params.SONAR_TEST_INCLUSIONS,
                  coverageExclusions: params.SONAR_COVERAGE_EXCLUSIONS,
                  lcovReportPaths: params.SONAR_LCOV_REPORT_PATHS,
                  tsconfigPaths: params.SONAR_TSCONFIG_PATHS,
                  extraProperties: params.SONAR_EXTRA_PROPERTIES
                )

              }
          }
        }
        stage('pnpm编译') {
          steps {
            script {
                // 获取当前任务名
                def jobName = env.JOB_BASE_NAME ?: (env.JOB_NAME ?: 'unknown-job').tokenize('/').last()

                // 获取用户传入的根目录，如果没有则默认为 JENKINS_HOME
                def baseCacheDir = params.PNPM_CACHE_DIR?.trim()
                if (!baseCacheDir) {
                  baseCacheDir = env.JENKINS_HOME
                }

                // 统一拼接子路径，确保一定包含 jobName
                def resolvedPnpmCacheDir = "${baseCacheDir}/pnpm-build-cache/${jobName}"

                // 调用共享库，传入所有配置参数
                def result = pnpmBuildProject(
                  // 基础参数
                  targetDir              : params.PNPM_TARGET_DIR,
                  timeoutMinutes         : params.PNPM_TIMEOUT_MINUTES,
                  outputDir              : params.PNPM_OUTPUT_DIR,

                  // 命令
                  installCommand         : params.PNPM_INSTALL_COMMAND,
                  buildCommand           : params.PNPM_BUILD_COMMAND,

                  // 缓存
                  cacheEnabled           : params.PNPM_CACHE_ENABLED,
                  pnpmCacheDir           : resolvedPnpmCacheDir,
                  cleanCacheBeforeInstall: params.PNPM_CLEAN_CACHE,

                  // 仓库认证（直接传参，无需 withCredentials）
                  pnpmRegistry           : params.PNPM_REGISTRY,
                  pnpmRegistryAuthBase64   : params. PNPM_REGISTRY_AUTH_BASE64,

                  // pnpm 特性
                  strictPeerDependencies : params.PNPM_STRICT_PEER,
                  autoInstallPeers       : params.PNPM_AUTO_INSTALL_PEERS,
                )
              }
          }
        }
      }
    }
    stage('buildKit构建镜像') {
      steps {
        script {
            def result = buildkitBuildImage(
            buildkitAddr    : params.BUILDKIT_SERVER_ADDR,
            certificateCode : params.BUILDKIT_CERTIFICATE_CODE,
            registryUrl     : params.BUILDKIT_REGISTRY_URL,
            registryProject     : params.BUILDKIT_REGISTRY_PROJECT,
            imageName       : params.BUILDKIT_IMAGE_NAME,
            credentialsId   : params.BUILDKIT_CREDENTIALS_ID,
            dockerfilePath  : params.BUILDKIT_DOCKERFILE_PATH,
            targetDir       : params.BUILDKIT_TARGET_DIR,
            imageTag        : params.BUILDKIT_IMAGE_TAG,
            tagStrategy     : params.BUILDKIT_TAG_STRATEGY,
            platforms       : params.BUILDKIT_PLATFORMS,
            cacheEnabled    : params.BUILDKIT_CACHE_ENABLED,
            cacheRef        : params.BUILDKIT_CACHE_REF
            )
            env.BUILD_IMAGE_REF = result.imageRef
          }
      }
    }
    stage('kube-nova 平台部署') {
      steps {
        script {
            def result = kubeNovaImageDeploy(
              deployConfig: params.KUBE_NOVA_DEPLOY_CONFIG,
              image       : env.BUILD_IMAGE_REF
            )

            echo "kube-nova 镜像升级完成，版本 ID：${result.versionId}，容器：${result.containerName}，镜像：${result.image}"
          }
      }
    }
  }
}

