    def resolvedSonarUserHome = "${baseSonarDir}/sonar-cache/${jobName}"

    def result = sonarScanPython(
      targetDir          : params.SONAR_PYTHON_TARGET_DIR,
      sonarHostUrl       : params.SONAR_PYTHON_HOST_URL,
      credentialsId      : params.SONAR_PYTHON_CREDENTIALS_ID,
      projectKey         : params.SONAR_PYTHON_PROJECT_KEY,
      projectVersion     : params.SONAR_PYTHON_PROJECT_VERSION,
      sourcesDir         : params.SONAR_PYTHON_SOURCES_DIR,
      exclusions         : params.SONAR_PYTHON_EXCLUSIONS,
      tests              : params.SONAR_PYTHON_TESTS,
      testInclusions     : params.SONAR_PYTHON_TEST_INCLUSIONS,
      coverageExclusions : params.SONAR_PYTHON_COVERAGE_EXCLUSIONS,
      coverageReportPaths: params.SONAR_PYTHON_COVERAGE_REPORT_PATHS,
      pythonVersion      : params.SONAR_PYTHON_VERSION,
      sonarUserHome      : resolvedSonarUserHome,
      wsTimeout          : params.SONAR_PYTHON_WS_TIMEOUT,
      timeoutMinutes     : params.SONAR_PYTHON_TIMEOUT_MINUTES,
      extraProperties    : params.SONAR_PYTHON_EXTRA_PROPERTIES
    )
  }
}

